// Symbole der installierbaren Web-App (PNG, base64), damit kein Dateizugriff nötig ist.
const dekodiere = (b64: string) =>
  Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const SYMBOLE: Record<string, Uint8Array<ArrayBuffer>> = {
  "icon-192.png": dekodiere(
    "",
  ),
  "icon-512.png": dekodiere(
    "",
  ),
  "apple-touch-icon.png": dekodiere(
    "",
  ),
};
